<script>

    // به صورت پیش فرض برای .btn_action فعال است.
    // در footer فراخوانی شده است.
    @if ($id == ".btn_action")

    // btn_action فقط برای فرم است.
    $(".btn_action").parent().submit(function () {
        $(".spinner-remove").remove();
        $(".btn_action").parent().append("<img src='data:image/svg+xml;base64,'/> در حال پردازش");
        $(".btn_action").remove();
        $(".dropdown-menu").remove();
        $(".dropdown-item").remove();
    });

    @else
    //   برای لینک و ...
    $("{{$id}}").click(function () {
        $(".spinner-remove").remove();
        $(".btn").parent().append("<img src='data:image/svg+xml;base64,'/> در حال پردازش");
        $(".btn").remove();
        $(".dropdown-menu").remove();
        $(".dropdown-item").remove();
        $(".spinner-remove").remove();
        return true;
    });

    @endif

    function spinner_run_for(){
        $(".spinner-remove").remove();
        $(".btn").parent().append("<img src='data:image/svg+xml;base64,'/> در حال پردازش");
        $(".btn").remove();
        $(".btn_action").parent().append("<img src='data:image/svg+xml;base64,'/> در حال پردازش");
        $(".btn_action").remove();
        $(".dropdown-menu").remove();
        $(".dropdown-item").remove();
    }
</script>
